import java.util.*; class Player05 implements Comparable<Player05>{String name;double battingAverage;int matchesPlayed;boolean injured;Player05(String n,double a,int m,boolean i){name=n;battingAverage=a;matchesPlayed=m;injured=i;}boolean isDraftable(){return matchesPlayed>=10;}boolean isDraftable(int min){return matchesPlayed>=min&&!injured;}public int compareTo(Player05 p){return Double.compare(p.battingAverage,battingAverage);}public String toString(){return name+" "+battingAverage;}} public class Week05Problem05{public static void main(String[]z){Scanner s=new Scanner(System.in);int n=s.nextInt();List<Player05>a=new ArrayList<>();for(int i=0;i<n;i++){Player05 p=new Player05(s.next(),s.nextDouble(),s.nextInt(),s.nextBoolean());if(p.isDraftable()||p.isDraftable(5))a.add(p);}Collections.sort(a);for(Player05 p:a)System.out.println(p);}}